// 对应 Folia src/components/wall/blockReflows.ts（生成数据，勿手改）：每个基础模板、每个被展开的槽各一套
// 让位布局——展开者占 6×6，其余 11 张退到小档位，整块仍正好铺满；下标按原槽位，砖保持身份。
// 编码：每张 4 个十六进制字符 x,y,cols,rows；顺序 = 模板(4) × 展开槽(12) × 槽(12)。
package com.guangyue.core.wall

internal object BlockReflowData {
    private const val DATA = ""

    /** [template][expandedSlot][slot] */
    val REFLOWS: List<List<List<BlockSlot>>> = List(4) { t ->
        List(12) { e ->
            List(12) { i ->
                val o = ((t * 12 + e) * 12 + i) * 4
                BlockSlot(DATA[o].digitToInt(16), DATA[o + 1].digitToInt(16), DATA[o + 2].digitToInt(16), DATA[o + 3].digitToInt(16))
            }
        }
    }
}
